begin;
create table if not exists finance.fee_groups(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,active boolean not null default true,unique(tenant_id,code));
create table if not exists finance.fee_group_classes(tenant_id uuid not null references app.tenants(id) on delete cascade,fee_group_id uuid not null references finance.fee_groups(id) on delete cascade,class_id uuid not null references academics.classes(id) on delete cascade,primary key(fee_group_id,class_id));
create table if not exists finance.fee_schedules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,fee_group_id uuid references finance.fee_groups(id),term_id uuid references academics.terms(id),fee_item_id uuid references finance.fee_items(id),amount numeric(14,2) not null check(amount>=0),due_date date,active boolean not null default true);
create table if not exists finance.fee_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),academic_year_id uuid references academics.academic_years(id),opening_balance numeric(14,2) not null default 0,status text not null default 'active',unique(tenant_id,student_id,academic_year_id));
create table if not exists finance.fee_allocations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,account_id uuid not null references finance.fee_accounts(id) on delete cascade,fee_schedule_id uuid references finance.fee_schedules(id),description text not null,amount numeric(14,2) not null,allocated_at timestamptz not null default now(),created_by uuid references authn.users(id));
create table if not exists finance.fee_transactions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,account_id uuid not null references finance.fee_accounts(id) on delete cascade,transaction_type text not null check(transaction_type in('charge','payment','discount','refund','adjustment','reversal')),amount numeric(14,2) not null,reference text,receipt_no text,related_payment_id uuid references finance.payments(id),posted_by uuid references authn.users(id),posted_at timestamptz not null default now(),reversed_by uuid references authn.users(id),reversed_at timestamptz,reversal_reason text);
create index if not exists fee_transactions_account_time_idx on finance.fee_transactions(tenant_id,account_id,posted_at desc);
create table if not exists finance.guardian_contact_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),guardian_id uuid references app.guardians(id),contact_method text not null,outcome text,notes text,follow_up_on date,recorded_by uuid references authn.users(id),recorded_at timestamptz not null default now());
create table if not exists finance.hold_policy(tenant_id uuid primary key references app.tenants(id) on delete cascade,enabled boolean not null default false,minimum_outstanding numeric(14,2) not null default 0,block_reports boolean not null default false,block_transcripts boolean not null default false,updated_by uuid references authn.users(id),updated_at timestamptz not null default now());
create table if not exists finance.hold_overrides(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),reason text not null,expires_at timestamptz,created_by uuid references authn.users(id),created_at timestamptz not null default now(),revoked_at timestamptz);
create table if not exists finance.salary_grades(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,base_amount numeric(14,2) not null default 0,active boolean not null default true,unique(tenant_id,code));
create table if not exists finance.payroll_profiles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,staff_id uuid not null references app.staff(id),salary_grade_id uuid references finance.salary_grades(id),base_salary numeric(14,2) not null default 0,bank_details jsonb not null default '{}'::jsonb,tax_identifier text,pension_identifier text,active boolean not null default true,unique(tenant_id,staff_id));
create table if not exists finance.payroll_rules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,rule_type text not null check(rule_type in('earning','deduction')),calculation_type text not null default 'fixed',value numeric(14,4) not null default 0,active boolean not null default true,unique(tenant_id,code));
create table if not exists finance.payroll_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,payroll_run_id uuid not null references finance.payroll_runs(id) on delete cascade,staff_id uuid not null references app.staff(id),gross_amount numeric(14,2) not null default 0,total_deductions numeric(14,2) not null default 0,net_amount numeric(14,2) not null default 0,status text not null default 'calculated',paid_at timestamptz,unique(payroll_run_id,staff_id));
create table if not exists finance.payroll_item_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,payroll_item_id uuid not null references finance.payroll_items(id) on delete cascade,rule_id uuid references finance.payroll_rules(id),line_type text not null,description text not null,amount numeric(14,2) not null);
create table if not exists finance.teacher_loans(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,staff_id uuid not null references app.staff(id),principal numeric(14,2) not null check(principal>0),balance numeric(14,2) not null,installment_amount numeric(14,2),status text not null default 'active',issued_on date not null,matures_on date,created_by uuid references authn.users(id));

do $$declare t text; begin foreach t in array array['fee_groups','fee_group_classes','fee_schedules','fee_accounts','fee_allocations','fee_transactions','guardian_contact_events','hold_policy','hold_overrides','salary_grades','payroll_profiles','payroll_rules','payroll_items','payroll_item_lines','teacher_loans'] loop perform app.install_tenant_policy('finance',t,true); end loop; end$$;
insert into app.schema_migrations(version) values ('0011_finance_enterprise') on conflict do nothing;
update app.release_identity set schema_version='0011' where edition='Edusentia Enterprise Neon Edition';
commit;
